import json, csv, re
from pathlib import Path

OUT=Path(__file__).resolve().parent
talks=[]; items=[]; problems=[]; corrections=[]

def talk(record,date,speaker,pages,title,summary):
    talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind='talk',summary=summary))

def item(record,pages,kind,title,notes,statement,refs=(),**kw):
    n=1+sum(x['record']==record for x in items)
    d=dict(id=f'1975-{record}.{n}',record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,
           reconstruction='',**{'class':'E'},fate='',present_status='As of November 2026, the reconstructed statement is standard.',
           literal_correctness='correct with missing hypotheses',publication_match='partial',verification='read the result',
           development='annotated',problem='',worth='',refs=list(refs),confidence='high',area='')
    d.update(kw);items.append(d);return d['id']

def problem(id,title,statement,occurrences,status,refs=()):
    problems.append(dict(id=id,title=title,statement=statement,occurrences=occurrences,status=status,status_date='2026-11',refs=list(refs)))

def correction(page,place,reads,should,evidence,typ='faithful_error',applies='both'):
    corrections.append(dict(page=page,place=place,transcription_reads=reads,should_read=should,evidence=evidence,applies_to=applies,type=typ))

def save():
    items.sort(key=lambda x:(x['record'],int(x['id'].split('.')[-1])))
    for obj in items+talks+problems:
        for k in ('notes','statement','reconstruction','fate','present_status','worth','summary','status'):
            if k in obj:
                obj[k]=re.sub(r'\b(Sections?|Theorems?|Lemmas?|Remarks?|Propositions?|Corollaries|April|March|November|October|February|January|December|June|July|May|August|September|in|through|published|received|revision|circulated)(?=\d)',r'\1 ',obj[k])
    # Repair the first drafting block's plain-parenthesis math while preserving
    # the existing inline and display math, including parentheses inside it.
    for x in items:
        if x['record']==386 or x['id']=='1975-387.1':
            for k in ('notes','statement','reconstruction'):
                chunks=re.split(r'(\\\(.*?\\\)|\\\[.*?\\\])',x[k],flags=re.S)
                for j in range(0,len(chunks),2):
                    chunks[j]=re.sub(r'\((?:[^()]|\([^()]*\))*\)',lambda m:r'\('+m[0][1:-1]+r'\)',chunks[j])
                x[k]=''.join(chunks)
                # Save is called after each record; inserting thin spaces must
                # remain idempotent when an earlier record is written again.
                x[k]=re.sub(r'(?<!\\),(?=d(?:\^|x|y))',r'\\,',x[k])
    for suffix,data in [('talks',talks),('items',items),('problems',problems)]:
        (OUT/f'c_{suffix}.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    with (OUT/'c_corrections.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader()
        escape={'_':r'\_','^':r'\textasciicircum{}','{':r'\{','}':r'\}','%':r'\%','&':r'\&','#':r'\#'}
        for row in corrections:
            w.writerow({k:''.join(escape.get(c,c) for c in v) if k in ('place','transcription_reads','should_read','evidence') else v for k,v in row.items()})

talk(386,'1976-03-15','A. M. Polyakov','P000643-P000649','Canonical quantization of Yang–Mills fields',r'''The mathematical text starts on P000644 after the conclusion of the preceding algebro-geometric discussion. Polyakov passes from the Yang--Mills Lagrangian to constrained Hamiltonian mechanics, separates longitudinal and transverse electric fields in Coulomb gauge, and proposes averaging the resulting charge kernel in the quantum vacuum. Several numerical factors and commutator signs are inconsistent in the manuscript; the reconstructed formulas below use one convention throughout. P000647 points ahead to the continuation on 5 April.''')
item(386,'P000644','definition','Yang–Mills potentials, curvature and action',r'''The notes take traceless anti-Hermitian (2\times2) matrices (A_\mu), write (A_\mu\in SU(2)) followed by ``Lie algebra'', and define (F_{\mu\nu}=\partial_\mu A_\nu-\partial_\nu A_\mu+g[A_\mu,A_\nu]).''',r'''A connection on a trivial (SU(2))-bundle is a one-form (A=A_\mu dx^\mu) with (A_\mu\in\mathfrak{su}(2)). Its curvature is (F=dA+gA\wedge A). Use the positive invariant inner product (\langle X,Y\rangle=-\operatorname{tr}(XY)) on the Lie algebra. The Euclidean action is (S_E=\frac14\int\langle F_{\mu\nu},F_{\mu\nu}\rangle,d^4x); Lorentzian contraction instead uses the spacetime metric.''',('jaffewitten2000yangmills',),fate=r'''These are the classical definitions; see \citet[Section 1]{jaffewitten2000yangmills}. The source's positive trace formula and anti-Hermitian convention cannot both give a nonnegative Euclidean action.''',literal_correctness='false as written',area='Gauge theory')
item(386,'P000644-P000645','construction','Legendre transformation and Gauss constraint',r'''The notes set (e_i=\dot A_i-D_iA_0), observe the absence of (\dot A_0), and introduce (h_i=\frac12\varepsilon_{ijk}F_{jk}). Both displayed Hamiltonians put a factor (1/2) on the (A_0)-term.''',r'''With (L=\frac12\int(\langle e,e\rangle-\langle h,h\rangle)), the canonical momenta are (e_i) and (e_0=0). Integration by parts, with boundary terms zero, gives
\[H=\frac12\int(\langle e,e\rangle+\langle h,h\rangle),d^3x-\int\langle A_0,D_ie_i\rangle,d^3x.\]
Variation in (A_0) imposes (D_ie_i=0). The coefficient of this last term is one, with the conventions just fixed.''',('arnowittfickler1962quantization','reinhardt2018coulomb'),reconstruction=r'''The displayed result follows directly from (\dot A=e+DA_0). A positive Lie-algebra inner product replaces the ambiguous bare trace. No global Hamiltonian phase space is asserted without boundary and function-space choices.''',fate=r'''Canonical constraint reduction predates the seminar: \citet[abstract]{arnowittfickler1962quantization}; the reconstructed Hamiltonian also agrees with \citet[Section 2, equations (1)--(5)]{reinhardt2018coulomb}. The 1962 paper's metadata and abstract, rather than its full derivation, were accessible.''',literal_correctness='false as written',area='Gauge theory')
item(386,'P000645','question','Propagation of the Gauss constraint',r'''The speaker asks whether (D_ie_i=0) continues to hold and writes a Poisson-bracket condition for (\rho=D_ie_i).''',r'''On the canonical phase space, set (G(\omega)=\int\langle\omega,D_ie_i\rangle). The gauge-invariant reduced Hamiltonian (H_0=\frac12\int(e^2+h^2)) obeys (\{G(\omega),H_0\}=0). Consequently Gauss's constraint propagates in temporal gauge; with an arbitrary multiplier (A_0), its evolution is an adjoint rotation and preserves the zero constraint surface.''',('arnowittfickler1962quantization',),reconstruction=r'''The source's bracket is the negative of the convention (\{A_i,e_j\}=\delta_{ij}\delta), although its Hamilton equations use that latter convention. The vanishing assertion is unaffected; the sign must be fixed when generating gauge transformations.''',fate=r'''This is part of the pre-existing first-order canonical formulation; \citet[abstract, discussion of constraint conservation]{arnowittfickler1962quantization}. The proof here is the elementary implication of gauge invariance, not an attribution of a newly announced theorem.''',verification='publisher metadata checked',publication_match='partial',area='Gauge theory')
item(386,'P000645','construction','Gauge covariance and transverse coordinates',r'''The transformation (A_i^\Omega=\Omega^{-1}A_i\Omega+g^{-1}\Omega^{-1}\partial_i\Omega) preserves \(\operatorname{tr}h^2\). The notes then write every field in terms of (a_i) with (\partial_i a_i=0) and a gauge matrix.''',r'''For smooth (\Omega:\mathbb R^3\to SU(2)), (F_{ij}^\Omega=\Omega^{-1}F_{ij}\Omega), so the magnetic energy is gauge invariant. Coulomb gauge (\partial_i a_i=0) is a local slice where its linearization (M=-\partial_iD_i(a)) is invertible after boundary conditions and residual constant transformations are fixed.''',('reinhardt2018coulomb',),reconstruction=r'''A local slice, not a globally unique decomposition, is the justified reading. Distinct gauge-equivalent transverse fields may exist.''',fate=r'''The Coulomb formulation remains useful, with its gauge-fixing determinant and Gribov restriction made explicit in \citet[Section 2]{reinhardt2018coulomb}.''',area='Gauge theory')
item(386,'P000646','construction','Longitudinal electric field and the Coulomb kernel',r'''The notes split (e_i=P_i+\partial_i\Psi), (\partial_iP_i=0), and call the longitudinal energy Coulomb energy. The commutator on the right of the Gauss equation changes order twice.''',r'''Fix (D_i=\partial_i+g[a_i,\cdot]) and (D_ie_i=\rho). Then
\[D_i\partial_i\Psi=\rho-g[a_i,P_i]=:\rho_{\rm tot}.\]
For transverse (a), (M=-\partial D=-D\partial), so (\Psi=-M^{-1}\rho_{\rm tot}) and
\[H_C=\tfrac12\langle\rho_{\rm tot},M^{-1}(-\Delta)M^{-1}\rho_{\rm tot}\rangle\]
when (M) is self-adjoint and invertible on the chosen domain. The cross term (\int P_i\partial_i\Psi) vanishes by integration by parts.''',('schwinger1962relativistic','reinhardt2018coulomb'),reconstruction=r'''The sign is forced by the source's definitions, rather than chosen to imitate a later convention for the gluonic charge. The notes omit (g) in the first version and reverse the bracket in the later versions.''',fate=r'''The source explicitly credits Schwinger. His 1962 radiation-gauge paper is an identified historical match at abstract level; the modern kernel is displayed in \citet[Section 2, equation (5)]{reinhardt2018coulomb}.''',literal_correctness='false as written',area='Gauge theory')
item(386,'P000646','claim','Recovery of the Abelian Coulomb energy',r'''For (g=0) the notes write (\Delta\Psi=\rho) and identify the energy with a double integral having kernel (1/|x-y|).''',r'''For a sufficiently decaying smooth charge on \(\mathbb R^3\), (\Psi(x)=-\int\rho(y)/(4\pi|x-y|),dy) solves (\Delta\Psi=\rho). Thus
\[\tfrac12\int|\nabla\Psi|^2,dx=\tfrac1{8\pi}\iint\frac{\rho(x)\rho(y)}{|x-y|},dx,dy.\]
Point charges require subtraction or regularization of divergent self energies.''',(),reconstruction=r'''This is an explicit reconstruction using \(-\Delta(4\pi|x|)^{-1}=\delta_0\); the notebook suppresses normalization constants. It follows directly by Green's identity.''',fate='The elementary electrostatic calculation supplies the exact normalization behind the source formula.',publication_match='none found',area='Gauge theory')
item(386,'P000646','method','Perturbation of the non-Abelian Gauss equation',r'''An inverse-Laplacian expansion and diagrams with zero, one and two insertions of (a_i) are written; the first correction contains no (g). The accompanying historical remark names Khriplovich and Gross.''',r'''For (P=0), formally write (L_a\Psi=\sum_i[a_i,\partial_i\Psi]). Then
\[(\Delta+gL_a)^{-1}\rho=\Delta^{-1}\rho-g\Delta^{-1}L_a\Delta^{-1}\rho+O(g^2).\]
For (P\ne0) one must also expand the source \(\rho-g[a_i,P_i]\). Analytic convergence requires an operator topology in which \(\|g\Delta^{-1}L_a\|<1\); no such estimate is supplied.''',('schwinger1962relativistic',),reconstruction=r'''This is the formal Neumann expansion of the preceding reconstructed equation. The list of physicists does not by itself specify a beta function, renormalization scheme, or an asymptotic-freedom theorem.''',fate=r'''Schwinger's pre-existing Coulomb-gauge program is identifiable \citep[abstract]{schwinger1962relativistic}; the particular omitted perturbative calculation attributed to Khriplovich and Gross is not identifiable from this page.''',literal_correctness='false as written',publication_match='thematic only',verification='publisher metadata checked',confidence='medium',area='Gauge theory')
item(386,'P000647','construction','Canonical quantization in Coulomb gauge',r'''The commutator is abbreviated as \([a(x),p(y)]=\delta(x-y)\).''',r'''For transverse components, the formal equal-time relation is
\[[a_i^a(x),P_j^b(y)]=i\hbar\delta^{ab}\left(\delta_{ij}-\frac{\partial_i\partial_j}{\Delta}\right)\delta(x-y).\]
A quantum Hamiltonian further requires regularization, ordering and the gauge-fixed inner product. The formula alone is not a construction of continuum Yang--Mills theory.''',('reinhardt2018coulomb',),fate=r'''The Schrödinger representation and the Faddeev--Popov density are described in \citet[Section 2]{reinhardt2018coulomb}. The transverse projector is forced by \(\partial_i a_i=\partial_iP_i=0\).''',literal_correctness='false as written',area='Gauge theory')
item(386,'P000646-P000647','method','Vacuum averaging of the charge interaction',r'''The kernel (F(x,y,a)) replaces (1/|x-y|), and (\delta E=\int\rho(x)\langle F(x,y,a)\rangle\rho(y),dx,dy) is proposed.''',r'''For specified external color sources, a regulated Coulomb-gauge vacuum expectation of (M^{-1}(-\Delta)M^{-1}) defines an instantaneous color-Coulomb contribution. Whether the full static-source ground-state energy grows linearly at large separation is the confinement question, not a consequence of taking this expectation.''',('reinhardt2018coulomb','jaffewitten2000yangmills'),**{'class':'C'},fate=r'''The approach has a substantial later literature; \citet[Sections 2--3]{reinhardt2018coulomb}. The relation to confinement requires separating instantaneous energy from the fully relaxed static potential; \citet[Section 5]{jaffewitten2000yangmills} distinguishes confinement from the Yang--Mills existence and mass-gap problem.''',present_status=r'''As of November 2026, this fragment supplies a formal route to the confinement problem GP-1975-10, not its solution. The notes specify neither a regulated vacuum nor a limiting construction.''',problem='GP-1975-10',worth='A precise comparison between the instantaneous Coulomb kernel and gauge-invariant static energy remains useful for understanding what this calculation can establish.',area='Gauge theory')
correction('P000644','Lie-algebra membership','A_mu in SU(2) (Lie alg.)','A_mu in su(2)','The written anti-Hermitian trace-zero condition is the Lie algebra condition; scan agrees with SU(2).')
correction('P000645','Legendre transformation','1/2 e(e+D A_0)+1/2 h^2','1/2(e^2+h^2)+e D A_0','Direct Legendre transformation; scan clearly retains one half on e D A_0.')
correction('P000645','integrated Hamiltonian','1/2 integral[e^2+h^2-A_0 D e]','1/2 integral(e^2+h^2)-integral A_0 D e','Integration by parts with the preceding normalization; scan checked.')
correction('P000646','three versions of the Gauss equation','rho+[P,a]; [a,P]; rho+g[a,P]','rho-g[a,P], with D=partial+g[a,.]','Expanding D(P+partial Psi)=rho fixes both g and commutator order; all conflicting versions occur in scan.')
correction('P000646','first perturbative correction','-Delta^{-1}[a,partial Delta^{-1}rho]','-g Delta^{-1}[a,partial Delta^{-1}rho] for P=0','Formal expansion of Delta+g ad(a)partial; no g visible in scan.')
correction('P000647','canonical commutator','[a(x),p(y)]=delta(x-y)','i hbar times color identity and transverse spatial projector','Both variables have already been restricted to transverse fields; normalization cannot be the unconstrained scalar delta.')
